pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // deploy original and immediately call disableInitializers via constructor
        c = new C();
        // The test will call proxiableUUID directly on the implementation (not via proxy).
        // Since the __self is address(this), a non-delegated call must originate from the implementation itself.
        // Hence we need to call it directly, which is allowed by _checkNotDelegated when address(this) == __self.
        // No initializer or setup needed; the function is pure-in-effect but reads immutable __self.
    }
    function testFuzz_property(uint256 dummy) public {
        // The fuzzer provides a dummy param to satisfy the fuzz requirement.
        // We call proxiableUUID directly. Since we are testing the implementation directly,
        // the call satisfies notDelegated.
        bytes32 returnedSlot = c.proxiableUUID();
        bytes32 expectedSlot = bytes32(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
        assertTrue(returnedSlot == expectedSlot);
    }
}

