import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address accessControl, address nonTopLevelCaller) public {
        vm.assume(accessControl != address(0));
        vm.assume(nonTopLevelCaller != address(0));
        vm.assume(nonTopLevelCaller != address(c));
        vm.assume(nonTopLevelCaller != address(this));

        // Initialize first time - should succeed
        c.initialize(accessControl);

        // Attempt re-initialization from a non-top-level call (e.g., via a helper contract that calls initialize)
        Reinitializer helper = new Reinitializer(address(c));
        vm.prank(nonTopLevelCaller);
        bool success;
        try helper.attemptReinitialize(accessControl) {
            success = true;
        } catch {
            success = false;
        }

        // The reference should revert re-initialization (success == false),
        // the mutant may allow it to succeed (success == true).
        assertFalse(success);
    }
}

