pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address initialAdmin, address secondAdmin) public {
        vm.assume(initialAdmin != address(0));
        vm.assume(secondAdmin != address(0));

        // Deploy a factory that will delegatecall into c's initialize
        ProxyFactory factory = new ProxyFactory();

        // First normal top-level initialization
        c.initialize(initialAdmin);

        // Now attempt re-initialization via delegatecall from the factory
        // This is a top-level call from the factory's perspective,
        // but within c, _initializing will be false, making isTopLevelCall = true.
        bool reinitSuccess;
        try factory.delegateInitialize(address(c), secondAdmin) {
            reinitSuccess = true;
        } catch {
            reinitSuccess = false;
        }

        // The reference C must reject re-initialization (revert).
        // The mutant allows it because it only checks _initialized == 0.
        assertTrue(!reinitSuccess, "Re-initialization should revert");
    }
}

contract ProxyFactory {
    function delegateInitialize(address target, address admin) external {
        (bool success, ) = target.delegatecall(abi.encodeWithSignature("initialize(address)", admin));
        if (!success) {
            revert();
        }
    }
}

