pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newAccessControl, address secondAccessControl) public {
        vm.assume(newAccessControl != address(0));
        vm.assume(secondAccessControl != address(0));
        // Deploy a minimal proxy that routes all calls to the current implementation via delegatecall
        Proxy p = new Proxy(address(c));
        // First initialize through the proxy
        p.initialize(newAccessControl);
        // Record the access control slot value after first init
        bytes32 slot = 0xb413d65cb88f23816c329284a0d3eb15a99df7963ab7402ade4c5da22bff6b00;
        address accessControlAfterFirst = address(uint160(uint256(vm.load(address(p), slot))));
        // Second initialize attempt
        bool secondOk = true;
        try p.initialize(secondAccessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        address accessControlAfterSecond = address(uint160(uint256(vm.load(address(p), slot))));
        // Rule: second call must either revert OR leave the access control unchanged (not overwritten)
        bool unchanged = (accessControlAfterSecond == accessControlAfterFirst);
        assertTrue(!secondOk || unchanged);
    }
}

contract Proxy {
    address implementation;
    constructor(address _impl) { implementation = _impl; }
    fallback() external payable {
        address impl = implementation;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}

