pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl1, address accessControl2) public {
        vm.assume(accessControl1 != address(0) && accessControl2 != address(0));
        vm.assume(accessControl1 != accessControl2);
        address proxy = address(c);

        // First initialization
        c.initialize(accessControl1);

        // Second initialization attempt
        bool secondCallSucceeded;
        try c.initialize(accessControl2) {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        // If the second call did not revert, the access control must NOT have changed.
        // Reference: second call always reverts, so access control never changes -> true.
        // Mutant: second call may succeed and change access control -> false when accessControl2 != accessControl1.
        bool accessControlUnchanged = true;
        if (secondCallSucceeded) {
            // Read the access control via calling a function that uses it.
            // rate() is a public external that indirectly uses access control via _checkAccess in _authorizeUpgrade,
            // but here we can use a view function? No public getter for accessControl exists.
            // We can test access control indirectly: call a function that requires specific access.
            // Since we can't read accessControl directly, we use the fact that setSlopes requires access.
            // We'll call setSlopes with prank(accessControl1) and prank(accessControl2) and see who succeeds.
            // But we need a general assertion. Instead, we can check the revert behavior of initialize itself:
            // The rule is: if the second call succeeds, the access control must be the same as after the first.
            // Since the reference always reverts, the implication holds vacuously.
            // The mutant allows overwrite, so if secondCallSucceeded && accessControl2 != accessControl1,
            // the access control changed. We detect this by calling a privileged function.
            // However, we can't easily read accessControl without a getter. We use the fact that setSlopes
            // is guarded by checkAccess. We prank as accessControl2 and try to call setSlopes;
            // if it succeeds, access control was overwritten to accessControl2.
            // But we need a general property that holds for all inputs. Since we don't have a getter,
            // we can assert that if secondCallSucceeded, then accessControl2 == accessControl1.
            // But that's not directly observable. Instead, we observe that the second call to initialize
            // with a different access control does NOT revert in the mutant, while it DOES in the reference.
            // The property: a second call to initialize must always revert.
            // We can assert that secondCallSucceeded is false.
            // That is a property that holds for all inputs on the reference: any second initialize reverts.
            // The mutant fails this for accessControl2 != accessControl1.
            // That matches the requirement: "For any admissible input, the correct contract obeys this rule; the buggy one violates it for some input."
            // So we can simply assert that the second call reverts.
            // However, the instruction says: "Reason from the change above so the rule actually targets the difference."
            // The difference is that the mutant allows re-initialization. The property "second call always reverts" directly targets that.
            accessControlUnchanged = false; // dummy to use the variable
        }

        // The general rule: after a successful initialize, any subsequent initialize call MUST revert.
        assertTrue(!secondCallSucceeded);
    }
}

