    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        // deploy a helper that implements a minimal IAccessControl to allow initialization
        MockAccessControl helper = new MockAccessControl();
        address _accessControl = address(helper);
        // first initialization
        c.initialize(_accessControl);
        // reinitializer(1) must always fail for the correct contract
        // we fuzz the accessControl argument passed to reinitializer(1) via a helper call
        bool okR1 = false;
        try this.helper_call_reinitializer1(c, accessControl) {
            okR1 = true;
        } catch {
            okR1 = false;
        }
        assertTrue(!okR1);
    }
    // external helper to call reinitializer(1) from this test contract context,
    // because the reinitializer modifier is internal; we call a function on C that uses the modifier?
    // The C contract does not expose any reinitializer(1) function.
    // We need a function that applies reinitializer(1). The bug is observed via a reinitialization attempt.
    // Solution: we extend C in a helper to expose a reinitializer call.
    function helper_call_reinitializer1(C target, address accessControl) external {
        // We'll call a function on a wrapper that invokes reinitializer(1) internally.
        // Since C does not expose this, we need a minimal wrapper that inherits from C and adds an external call that applies reinitializer(1).
        // This wrapper is deployed in setUp or here. We'll deploy a single instance in setUp.
        // But we cannot modify setUp signature. We'll deploy a wrapper per this call? Not efficient.
        // Let's design: we add a helper contract below that wraps C and exposes a reinitializer(1) call.
    }
}

contract MockAccessControl {
    function checkAccess(bytes4, address, address) external pure returns (bool) { return true; }
}

contract C_Reinitializer_Wrapper is C {
    function callReinitializer(uint64 version, address accessControl) external reinitializer(version) {
        // reinitializer block: we just initialize again
        __Access_init(accessControl);
        __UUPSUpgradeable_init();
    }
}

