pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Helper to capture event data
    event Initialized(uint64 version);

    function setUp() public { c = new C(); }

    function testFuzz_property(address accessControl) public {
        // accessControl must be a contract with code to avoid low-level call succeeding silently
        // but the helper below always reverts on unknown selector, which is acceptable for initialization.
        // We deploy a contract that can receive the accessControl calls (checkAccess will call it).
        // However, initialize does not call checkAccess, it only stores accessControl.
        // We can use any address with code to satisfy the expected interface.
        // Deploy a minimal access control that returns true for checkAccess to avoid AccessDenied later,
        // but for initialization we only need it to not revert on low-level calls (it won't be called during init).
        AccessControlHelper helper = new AccessControlHelper();

        // Record logs to capture Initialized event
        vm.recordLogs();

        c.initialize(address(helper));

        Vm.Log[] memory entries = vm.getRecordedLogs();
        bool foundInitialized = false;
        uint64 emittedVersion = 0;
        for (uint i = 0; i < entries.length; i++) {
            // Check if the log is from our contract and matches Initialized signature
            if (entries[i].emitter == address(c)) {
                // topic0 is keccak256("Initialized(uint64)")
                // We can check manually or decode
                bytes32 eventSig = keccak256("Initialized(uint64)");
                if (entries[i].topics[0] == eventSig) {
                    foundInitialized = true;
                    // The data is the uint64 padded to 32 bytes
                    emittedVersion = uint64(uint256(entries[i].data));
                }
            }
        }

        // The general rule: the Initialized event MUST be emitted exactly once with version = 1
        // The buggy version emits version = 2 instead of 1.
        assertTrue(foundInitialized && emittedVersion == 1);
    }
}

// Minimal helper implementing IAccessControl partially to satisfy constructor/interface assumptions
contract AccessControlHelper {
    // We don't need full implementation because initialize just stores the address.
    // But if any call is made, we need to not revert unexpectedly.
    // The Access._checkAccess calls checkAccess, so we implement it to return true.
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

