        Vm.Log[] memory logs = vm.getRecordedLogs();
        bool foundInitialized1 = false;
        for (uint i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == keccak256("Initialized(uint64)")) {
                uint64 version = abi.decode(logs[i].data, (uint64));
                if (version == 1) {
